-- =============================================================================
-- 20261119000001 — iam 权限两表 id 补 IDENTITY（草案 A）
-- =============================================================================
-- 改前事实（2026-11-19 生产只读复核，PGOPTIONS=-cdefault_transaction_read_only=on）:
--   * iam.tenant_permissions / iam.tool_permissions 均存在，均 0 行；
--   * 两表 id 均为 bigint NOT NULL 且 column_default 为空、attidentity=''；
--   * 不存在 id 序列；public.tenant_permissions 也在（0 行），本轮不处理。
-- 影响：INSERT 不带 id 当前必失败；补 GENERATED BY DEFAULT AS IDENTITY 后可直接自增。
-- 幂等：已是 identity 则跳过；存在非 identity 默认值则硬失败，避免掩盖未知状态。
-- 起点：按 COALESCE(max(id),0)+1 计算；0 行时为 1，不会与应用已有数据冲突。
-- =============================================================================
DO $$
DECLARE
  target text;
  rel regclass;
  next_id bigint;
  has_identity boolean;
  has_default boolean;
BEGIN
  FOREACH target IN ARRAY ARRAY['iam.tenant_permissions', 'iam.tool_permissions']
  LOOP
    rel := to_regclass(target);
    IF rel IS NULL THEN
      RAISE EXCEPTION '前置断言失败：% 不存在，不能补 IDENTITY', target;
    END IF;

    SELECT (a.attidentity <> ''), a.atthasdef
      INTO has_identity, has_default
      FROM pg_attribute a
     WHERE a.attrelid = rel
       AND a.attname = 'id'
       AND NOT a.attisdropped;

    IF NOT FOUND THEN
      RAISE EXCEPTION '前置断言失败：%.id 列不存在', target;
    END IF;

    IF has_identity THEN
      RAISE NOTICE '% 已是 identity，跳过', target;
      CONTINUE;
    END IF;

    IF has_default THEN
      RAISE EXCEPTION '前置断言失败：%.id 已存在非 identity 默认值，拒绝自动改造', target;
    END IF;

    EXECUTE format('SELECT COALESCE(max(id), 0) FROM %s', rel) INTO next_id;
    EXECUTE format(
      'ALTER TABLE %s ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH %s)',
      rel, next_id + 1);
    RAISE NOTICE '% 已补 identity，起点 %', target, next_id + 1;
  END LOOP;
END $$;
